import {militaryPractice} from '../data/military-catalogue.mjs';
import { assessments } from '../data/assessments.mjs';
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const DAY=86400000;
function dateValue(date){if(!/^\d{4}-\d{2}-\d{2}$/.test(date))throw Error('Enter a valid calendar date.');const d=Date.parse(date+'T00:00:00Z');if(!Number.isFinite(d)||new Date(d).toISOString().slice(0,10)!==date)throw Error('Enter a valid calendar date.');return d;}
export function buildProgression({today,deadline,baseline,load,days,goal,equipment,step}){
 const start=dateValue(today),finish=dateValue(deadline),remaining=Math.floor((finish-start)/DAY),weeks=Math.min(12,Math.floor(remaining/7));
 if(weeks<2)throw Error('Less than two full weeks remain. Do not cram more training into the available time; review the requirements and your readiness.');
 if(!Number.isFinite(baseline)||baseline<10||baseline>600||!Number.isFinite(load)||load<0||load>50||!Number.isInteger(days)||days<2||days>4||![0,5,10].includes(step)||!['distance','selection','intensity','community'].includes(goal)||!['pack','bodyweight','weights'].includes(equipment))throw Error('Check the training inputs.');
 if(equipment==='bodyweight'&&load!==0)throw Error('Without a pack, enter zero load.');
 let long=baseline;const rows=[];
 for(let w=1;w<=weeks;w++){
  const recovery=w===weeks||w%4===0;
  if(w>1&&!recovery&&w%4!==1)long=Math.min(600,long+step);
  const minutes=recovery?Math.max(10,Math.round(long*.7)):long;
  const steady=Math.max(10,Math.round(minutes*.65));
  const sessions=[`${steady} min steady, familiar terrain.`,`${minutes} min ${goal==='distance'?'steady distance with a refuel plan':goal==='selection'?'controlled test-related practice; split across activities if necessary':goal==='intensity'?'controlled pace or hill practice, including recovery':'crew route with agreed pace and alternatives'}.`];
  if(days>=3)sessions.push(equipment==='weights'?'Controlled strength with familiar weights.':'Controlled bodyweight strength and mobility.');
  if(days===4)sessions.push('Optional easy movement or rest.');
  rows.push({week:w,recovery,minutes,load,sessions});
 }
 return {remaining,weeks,rows,limited:remaining>84};
}
export function renderProgression(){return `<section class="content-panel tool-panel" id="progression"><h2>Plan the weeks before your goal</h2><p>Make a repeatable block from your current capacity and target date. Choose a small increase in duration or hold the same duration; the plan keeps pack load fixed. Reassess before increasing work. This is not a prediction of readiness.</p><form id="block-form"><div class="tool-grid"><label>Target date<input id="block-date" type="date" required></label><label>Goal<select id="block-goal"><option value="distance">Long-distance event</option><option value="selection">Fitness assessment</option><option value="intensity">Pace and hills</option><option value="community">Shared challenge</option></select></label><label>Recent repeatable session (min)<input id="block-baseline" type="number" min="10" max="600" value="45" required></label><label>Familiar pack load (kg)<input id="block-load" type="number" min="0" max="50" step="0.5" value="5" required></label><label>Sessions per week<select id="block-days"><option>2</option><option selected>3</option><option>4</option></select></label><label>Equipment<select id="block-equipment"><option value="pack">Pack</option><option value="weights">Pack and weights</option><option value="bodyweight">Bodyweight only</option></select></label><label>Optional increase in longer session<select id="block-step"><option value="0">Hold current duration</option><option value="5">5 minutes on a build week</option><option value="10">10 minutes on a build week</option></select></label></div><button type="submit" class="button button-primary">Build training block</button></form><div id="block-output" class="tool-output" role="status">Choose your date and current capacity.</div></section>`;}
export function bindProgression(){const $=id=>document.querySelector('#'+id),f=$('block-form');if(!f)return;f.addEventListener('submit',e=>{e.preventDefault();try{const now=new Date(),today=[now.getFullYear(),String(now.getMonth()+1).padStart(2,'0'),String(now.getDate()).padStart(2,'0')].join('-');const r=buildProgression({today,deadline:$('block-date').value,goal:$('block-goal').value,baseline:Number($('block-baseline').value),load:Number($('block-load').value),days:Number($('block-days').value),equipment:$('block-equipment').value,step:Number($('block-step').value)});$('block-output').innerHTML=`<h3>${r.weeks} full weeks · ${r.remaining} days to target</h3><p>${r.limited?'Start with this 12-week block and reassess before planning the remainder. ':''}The last week reduces duration; confirm any event-specific taper separately. Progress only if the preceding work was repeatable, recovery adequate and technique consistent.</p><div class="progression-weeks">${r.rows.map(w=>`<section><h4>Week ${w.week} · ${w.recovery?'Easier / review':'Build or repeat'} · ${w.load} kg familiar load</h4><ul>${w.sessions.map(x=>`<li>${esc(x)}</li>`).join('')}</ul></section>`).join('')}</div>`;}catch(e){$('block-output').textContent=e.message;}});}
const practice={...militaryPractice,
 'ntoa-pfq':['Record each timed event separately; use the prescribed technique, order and rest.','Combine controlled running intervals and bodyweight work; rehearse the test format after building repeatability.'],
 rasp:['Keep rucking, running and swimming preparation distinct.','Record comparable distance, terrain and pack weight; do not invent a ruck time limit that is not in the public overview.'],
 'norwegian-armed-forces':['Choose the applicable scoring table first.','Practise the run, pulling strength and jumping or throwing technique separately before combining practice.'],
 artillerijaeger:['Check the full entry criteria and equipment rules.','Build loaded movement, unloaded running, strength and supervised swimming separately; do not begin by attempting the selection load at selection pace.'],
 'nsw-pct':['Rehearse the published agility layout and movement standards.','Record grip, bridge, jump, push-up and shuttle results separately; work on the weakest component.'],
 'danish-police':['Use the applicant criteria and official six-part test instructions.','Practise the relevant warm-up, speed, jump, pull-up, press and run components using the published technique.'],
 'army-aft':['Use the appropriate current scoring table.','Practise the lift and carry events with appropriate equipment and technique before rehearsing them in combination.'],
 'uk-police-jrft':['Practise the published 15-metre shuttle protocol, not a substitute 20-metre test.','Build aerobic capacity and controlled turns; confirm the role-specific standard.']
};
export function renderAssessmentPractice(){return `<section class="tool-panel assessment-practice"><h2>Prepare for your specific test</h2><p>Choose the programme to review its published components and preparation priorities. The organiser sets the actual standards.</p><label>Assessment<select id="prep-test">${assessments.map(a=>`<option value="${a.id}">${esc(a.shortName)}</option>`).join('')}</select></label><div id="prep-output">${assessmentPractice(assessments[0].id)}</div></section>`;}
export function assessmentPractice(id){const a=assessments.find(x=>x.id===id);if(!a)return '';return `<h3>${esc(a.shortName)}</h3><ul>${a.components.map(x=>`<li>${esc(x)}</li>`).join('')}</ul><h4>Preparation priorities</h4><ul>${practice[id].map(x=>`<li>${esc(x)}</li>`).join('')}</ul><p><a href="/testing-library/${a.id}/">Full test and official references</a></p>`;}
export function bindAssessmentPractice(){const s=document.querySelector('#prep-test');if(!s)return;s.addEventListener('change',()=>{document.querySelector('#prep-output').innerHTML=assessmentPractice(s.value);});}
